      (click)="themeToggled.emit()"
    >
      @if (isDark()) {
        <ng-icon hlmIcon name="lucideSun" />
      } @else {
        <ng-icon hlmIcon name="lucideMoon" />
      }
    </button>
    <hlm-avatar role="img" aria-label="Commander account">
      <span hlmAvatarFallback>CO</span>
    </hlm-avatar>
  </div>
</header>
