    label: 'Clearance tier',
    control: 'select',
    order: 5,
    help: 'Tier 1 is the lowest clearance, Tier 5 the highest.',
  }),
  notes: z.string().trim().max(500).meta({ label: 'Notes', control: 'textarea', order: 6 }),
});

export type RecruitModel = z.infer<typeof recruitSchema>;

