import pathlib
p=pathlib.Path('src/app/forms/zod-meta.ts')
s=p.read_text(encoding='utf-8')
old=s[s.index('export function formMeta'):]
new='''export function formMeta<S extends z.ZodObject<z.ZodRawShape>>(schema: S): FormMeta<S> {
  const meta: Record<string, FormFieldMeta> = {};
  for (const [name, field] of Object.entries(schema.shape)) {
    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
  }
  return meta as FormMeta<S>;
}
'''
s=s.replace(old,new)
p.write_text(s,encoding='utf-8')

p=pathlib.Path('src/app/recruit/recruit.schema.ts')
s=p.read_text(encoding='utf-8')
old="  clearanceTier: z.number().int().min(1).max(5).meta({"
assert old in s
s=s.replace(old,"  clearanceTier: z.literal(CLEARANCE_TIERS).meta({")
p.write_text(s,encoding='utf-8')
EOF
npx ng build > /tmp/build2.log 2>&1; echo "EXIT $?"; sed 's/\x1b\[[0-9;]*m//g' /tmp/build2.log | grep -v "^\s*$" | grep -iv "chunk-\|Lazy chunk\|Initial total\|Output location\|Names" | head -80

