  fs.createReadStream(file).pipe(res);
});
await new Promise((r) => server.listen(4311, r));
const base = 'http://localhost:4311';

const browser = await chromium.launch();
const problems = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
page.on('pageerror', (e) => problems.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') problems.push(`console: ${m.text()}`); });

async function overflow(p, label) {
  const dims = await p.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }));
  if (dims.sw > dims.cw) problems.push(`${label}: horizontal page overflow ${dims.sw} > ${dims.cw}`);
}

// 1. every route renders its real heading at three widths
const routes = [['/dashboard', 'Operations dashboard'], ['/roster', 'Roster'], ['/detail/HRO-0007', 'Silverwing'], ['/missions', 'Missions'], ['/threats', 'Threats'], ['/recruit', 'Recruit'], ['/settings', 'Settings']];
for (const width of [375, 768, 1280]) {
  await page.setViewportSize({ width, height: 900 });
  for (const [route, heading] of routes) {
    await page.goto(base + route);
    await page.waitForSelector('h1', { timeout: 5000 });
    await page.waitForTimeout(150);
    const h1 = (await page.locator('h1').first().textContent())?.trim() ?? '';
    if (!h1.includes(heading)) problems.push(`${width} ${route}: h1 "${h1}" lacks "${heading}"`);
    await overflow(page, `${width} ${route}`);
  }
}
await page.setViewportSize({ width: 1280, height: 900 });

// 2. edit on detail reaches dashboard and roster
await page.goto(base + '/detail/HRO-0007');
await page.waitForSelector('h1');
await page.getByRole('tab', { name: 'Edit' }).click();
await page.locator('#hero-alias').fill('Ada Voss-Renard');
await page.getByRole('button', { name: 'Save', exact: true }).click();
await page.waitForTimeout(200);
await page.goto(base + '/roster');
await page.waitForSelector('table');
const rosterAlias = await page.getByText('HRO-0007').locator('xpath=ancestor::tr').innerText();
console.log('roster row after edit contains new alias? (alias not shown in roster; shows name/ID)', rosterAlias.includes('Silverwing'));

// 3. deploy -> missions -> complete -> dashboard missions stat and hero record change
await page.goto(base + '/detail/HRO-0007');
await page.waitForSelector('h1');
await page.getByRole('button', { name: 'Deploy' }).click();
await page.waitForSelector('h1:has-text("Missions")');
const rowCount = await page.locator('tbody tr').count();
await page.getByRole('button', { name: /^Mark .* complete$/ }).first().click();
await page.waitForTimeout(150);
const footer = await page.locator('.missions__footer').innerText();
console.log('missions footer after settling:', footer.replace(/\s+/g, ' '));
await page.goto(base + '/dashboard');
await page.waitForSelector('h1');
const stat = await page.locator('app-stat-tile').nth(1).innerText();
console.log('dashboard missions tile:', stat.replace(/\s+/g, ' '));

// 4. topbar search lands on roster filtered by ?q=
await page.goto(base + '/dashboard');
await page.waitForSelector('h1');
await page.getByRole('searchbox', { name: 'Search heroes' }).fill('Null');
await page.keyboard.press('Enter');
await page.waitForURL(/roster\?q=Null/);
await page.waitForTimeout(150);
const footer2 = (await page.locator('.roster__footer').innerText()).replace(/\s+/g, ' ');
console.log('roster after search Null:', footer2);
if (!footer2.startsWith('1 of')) problems.push(`search did not filter roster: ${footer2}`);

// 5. recruit adds a hero that the roster and dashboard then show
await page.goto(base + '/recruit');
await page.waitForSelector('h1');
await page.locator('#recruit-name').fill('Test Recruit');
await page.locator('#recruit-alias').fill('Tester');
await page.locator('#recruit-notes').fill('Smoke test');
await page.getByRole('button', { name: 'Recruit hero' }).click();
await page.waitForURL(/detail\/HRO-0082/, { timeout: 5000 }).catch(() => problems.push('recruit did not navigate to new record'));
await page.goto(base + '/roster');
await page.waitForSelector('table');
const count = (await page.locator('.roster__footer').innerText()).replace(/\s+/g, ' ');
console.log('roster after recruit:', count);

// 6. theme switch on settings persists choice
await page.goto(base + '/settings');
await page.waitForSelector('h1');
await page.getByRole('switch', { name: 'Dark theme' }).click().catch(() => {});
const dark = await page.evaluate(() => document.documentElement.classList.contains('dark'));
console.log('dark class after switch:', dark);

await browser.close();
server.close();
console.log(problems.length ? 'PROBLEMS:\n' + problems.join('\n') : 'NO PROBLEMS');
EOF
