await page.locator('#recruit-alias').fill('Tester');
await page.getByRole('button', { name: 'Recruit hero' }).click();
await page.waitForURL(/detail\/HRO-\d+/, { timeout: 5000 }).catch(() => problems.push('D: recruit did not open record'));
console.log('D opened:', page.url());
await nav('Roster');
await page.waitForSelector('table');
const rosterCount = await text('.roster__footer');
console.log('D roster after recruit:', rosterCount);
if (!rosterCount.startsWith('13 of')) problems.push(`D: expected 13 heroes, got ${rosterCount}`);

// Flow E: settings theme switch
await nav('Settings');
await page.waitForSelector('h1');
const sw = page.locator('#settings-dark');
console.log('E switch count:', await sw.count(), 'aria-checked before:', await sw.getAttribute('aria-checked'));
await sw.click();
await page.waitForTimeout(150);
const dark = await page.evaluate(() => document.documentElement.classList.contains('dark'));
console.log('E dark class after click:', dark, 'aria-checked after:', await sw.getAttribute('aria-checked'));
if (!dark) problems.push('E: theme switch did not apply dark');

await browser.close();
server.close();
console.log(problems.length ? 'PROBLEMS:\n' + problems.join('\n') : 'NO PROBLEMS');
